//! HTTP/2 through the proxy, end to end.
//!
//! A real listener, a real `CONNECT`, real TLS with real ALPN on both sides,
//! and a real HTTP/2 client and origin — all in this process, on ports the
//! operating system chose. Nothing here reaches the network, and every
//! certificate is generated by the test that needs it.
//!
//! What is under test is that HTTP/2 is not a second proxy. A stream is an
//! exchange: it is evaluated by the same rules, captured into the same model,
//! given the same kind of id, timed on its own, and published on the same
//! event stream as an HTTP/1.1 request. The four ways a connection can be
//! made up — `h2` or `http/1.1` on each side — are all exercised, because the
//! two sides are decided separately and a proxy that only worked when they
//! agreed would not be a proxy.

mod support;

use std::collections::HashSet;

use hyper::{StatusCode, Version};
use proxy_engine::capture::Capture;
use proxy_storage::{CaptureConfig, EventPublisher, HttpVersion, Scheme, TrafficErrorKind};
use rules::{MapLocal, NewRule, Rule, RuleAction, RuleMatcher, RuleSet};
use support::http2::{Http2Client, Http2Origin, Http2Reply};
use support::{
    next_exchange, next_exchanges, no_further_exchange, trusting_all, HttpsClient, Proxy, TlsOrigin,
};

/// The host every TLS end in these tests is known by.
const HOST: &str = "localhost";

/// A proxy trusting `origin`'s CA, with the default capture.
async fn proxy_for(origin: &Http2Origin) -> Proxy {
    Proxy::trusting(origin.trust()).await
}

/// A client that trusts `proxy`'s CA and asks for HTTP/2.
fn client(proxy: &Proxy) -> Http2Client {
    Http2Client::trusting(proxy.trust())
}

/// An origin answering everything with `200 OK` and a short body.
async fn echoing_origin() -> Http2Origin {
    Http2Origin::start(HOST, |request| {
        Http2Reply::ok(format!("{} {}", request.method, request.path))
            .with_header("content-type", "text/plain")
    })
    .await
}

// ---------------------------------------------------------------------------
// HTTP/2 client → HTTP/2 origin
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread")]
async fn an_http_2_get_reaches_an_http_2_origin_and_comes_back() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/users")
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.version, Version::HTTP_2);
    assert_eq!(response.body_text(), "GET /users");

    let received = origin.only_request();
    assert_eq!(received.version, Version::HTTP_2);
    assert_eq!(received.method, "GET");

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_http_2_post_carries_its_body_to_the_origin() {
    let origin = Http2Origin::start(HOST, |request| {
        Http2Reply::ok(format!("received {} bytes", request.body.len()))
    })
    .await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let response = connection
        .send(
            "POST",
            "/orders",
            &[("content-type", "application/json")],
            br#"{"item":"widget","quantity":3}"#.to_vec(),
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "received 30 bytes");

    let received = origin.only_request();
    assert_eq!(received.method, "POST");
    assert_eq!(received.body_text(), r#"{"item":"widget","quantity":3}"#);
    assert_eq!(received.header("content-type"), Some("application/json"));

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_body_that_is_not_text_reaches_the_origin_byte_for_byte() {
    let origin = Http2Origin::start(HOST, |request| Http2Reply::ok(request.body.clone())).await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    // Every byte value, including the ones no UTF-8 decoder accepts.
    let binary: Vec<u8> = (0..=255_u8).collect();

    let response = connection.send("PUT", "/blob", &[], binary.clone()).await;

    assert_eq!(response.body, binary);
    assert_eq!(origin.only_request().body, binary);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn the_request_headers_the_client_sent_reach_the_origin() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    connection
        .send(
            "GET",
            "/x",
            &[
                ("accept", "application/json"),
                ("authorization", "Bearer token"),
                ("x-request-id", "abc123"),
            ],
            Vec::new(),
        )
        .await;

    let received = origin.only_request();
    assert_eq!(received.header("accept"), Some("application/json"));
    // The client's own credentials are for the origin, not for the proxy.
    assert_eq!(received.header("authorization"), Some("Bearer token"));
    assert_eq!(received.header("x-request-id"), Some("abc123"));

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn the_response_headers_the_origin_sent_reach_the_client() {
    let origin = Http2Origin::responding_with(
        HOST,
        Http2Reply::ok("{}")
            .with_header("content-type", "application/json")
            .with_header("x-served-by", "origin")
            .with_header("set-cookie", "a=1")
            .with_header("set-cookie", "b=2"),
    )
    .await;
    let proxy = proxy_for(&origin).await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/")
        .await;

    assert_eq!(response.header("content-type"), Some("application/json"));
    assert_eq!(response.header("x-served-by"), Some("origin"));
    let cookies: Vec<&str> = response
        .headers
        .iter()
        .filter(|(name, _)| name == "set-cookie")
        .map(|(_, value)| value.as_str())
        .collect();
    assert_eq!(cookies, ["a=1", "b=2"]);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_status_the_origin_chose_is_the_one_the_client_gets() {
    let origin =
        Http2Origin::responding_with(HOST, Http2Reply::status(StatusCode::NOT_FOUND, "gone")).await;
    let proxy = proxy_for(&origin).await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/missing")
        .await;

    assert_eq!(response.status, 404);
    assert_eq!(response.body_text(), "gone");

    proxy.stop().await;
}

