#[tokio::test(flavor = "multi_thread")]
async fn the_pseudo_headers_reach_the_origin_as_pseudo_headers() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let authority = origin.authority();

    client(&proxy)
        .connect(proxy.addr(), &authority, HOST)
        .await
        .send("PATCH", "/api/users/7?fields=name", &[], Vec::new())
        .await;

    let received = origin.only_request();
    assert_eq!(received.method, "PATCH");
    assert_eq!(received.scheme.as_deref(), Some("https"));
    assert_eq!(received.authority.as_deref(), Some(authority.as_str()));
    assert_eq!(received.path, "/api/users/7?fields=name");

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_http_2_request_does_not_reach_the_origin_carrying_a_host_header() {
    // `:authority` and `Host` are the same fact, and sending both is how the
    // two come to disagree. The proxy translates rather than duplicates.
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;

    client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/x")
        .await;

    assert_eq!(origin.only_request().header("host"), None);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn the_headers_http_2_forbids_never_reach_an_http_2_client() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/x")
        .await;

    for forbidden in ["connection", "keep-alive", "transfer-encoding", "upgrade"] {
        assert_eq!(
            response.header(forbidden),
            None,
            "{forbidden} was sent on an HTTP/2 stream"
        );
    }

    proxy.stop().await;
}

// ---------------------------------------------------------------------------
// Multiplexing
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread")]
async fn several_streams_on_one_connection_become_several_exchanges() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let mut events = proxy.events();
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let paths = ["/get", "/headers", "/anything", "/status/404"];
    let answers = connection.send_concurrently(&paths).await;

    // Every stream got its own answer, and got its own answer.
    assert_eq!(answers.len(), paths.len());
    for path in paths {
        let answer = answers.get(path).expect("every stream is answered");
        assert_eq!(answer.status, 200);
        assert_eq!(
            answer.body_text(),
            format!("GET {path}"),
            "{path} was answered with another stream's body"
        );
    }

    // One TLS connection to the origin, not four: the streams shared it.
    assert_eq!(origin.connections(), 1);
    assert_eq!(origin.requests().len(), paths.len());

    // And four exchanges came out, one per stream, each with an id of its own.
    let exchanges = next_exchanges(&mut events, paths.len()).await;
    let ids: HashSet<_> = exchanges.iter().map(|exchange| exchange.id).collect();
    assert_eq!(ids.len(), paths.len(), "two streams shared an exchange id");

    let urls: HashSet<String> = exchanges
        .iter()
        .map(|exchange| exchange.request.url.clone())
        .collect();
    for path in paths {
        assert!(
            urls.contains(&format!("https://{}{path}", origin.authority())),
            "{path} was not captured"
        );
    }
    no_further_exchange(&mut events).await;

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn each_streams_body_is_its_own() {
    let origin = Http2Origin::start(HOST, |request| {
        // The reply repeats what the request carried, so a body that was
        // mixed up between streams comes back to the wrong one.
        Http2Reply::ok(request.body.clone())
    })
    .await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let bodies = ["first-stream", "second-stream", "third-stream"];
    // Every stream is started before any of them is awaited, so all three are
    // in flight on the one connection at once.
    let streams: Vec<_> = bodies
        .iter()
        .enumerate()
        .map(|(index, body)| {
            let connection = connection.clone();
            let body = (*body).to_owned();
            let path = format!("/stream/{index}");

            tokio::spawn(async move {
                let response = connection
                    .send("POST", &path, &[], body.clone().into_bytes())
                    .await;

                (body, response)
            })
        })
        .collect();

    for stream in streams {
        let (sent, response) = stream.await.expect("the stream task does not panic");

        assert_eq!(response.body_text(), sent);
    }

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_connection_stays_open_for_stream_after_stream() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    // One at a time, in sequence: an HTTP/1.1 session would have closed after
    // the first of these.
    for index in 0..5 {
        let response = connection
            .send("GET", &format!("/again/{index}"), &[], Vec::new())
            .await;

        assert_eq!(response.status, 200);
    }

    assert_eq!(origin.requests().len(), 5);
    assert_eq!(origin.connections(), 1);

    proxy.stop().await;
}

// ---------------------------------------------------------------------------
// Rules
// ---------------------------------------------------------------------------

/// A rule set holding one rule, matching `host` and `path`.
///
/// The same `Rule`, `RuleMatcher` and `RuleSet` the HTTP/1.1 rule tests build
/// and the running proxy loads: an HTTP/2 stream meets the rules that already
/// existed, and there is no HTTP/2 matcher to write.
fn one_rule(name: &str, host: &str, path: &str, action: RuleAction) -> RuleSet {
    let matcher = RuleMatcher::any().with_host(host).with_path(path);
    let rule = Rule::create(NewRule::new(name, matcher, action)).expect("a valid rule");

    RuleSet::new([rule])
}

/// A `Block` answering with `status`.
fn block(status: u16) -> RuleAction {
    RuleAction::block_with(status)
}

/// A `MapRemote` to `url`.
fn map_remote(url: &str) -> RuleAction {
    RuleAction::map_remote(url).expect("a valid mapped URL")
}

#[tokio::test(flavor = "multi_thread")]
async fn a_blocked_stream_is_the_only_one_that_is_blocked() {
    let origin = echoing_origin().await;
    let proxy = Proxy::ruled(
        origin.trust(),
        Capture::with_defaults(),
        one_rule("block it", HOST, "/blocked", block(403)),
    )
    .await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let answers = connection
        .send_concurrently(&["/allowed", "/blocked", "/also-allowed"])
        .await;

    assert_eq!(answers["/blocked"].status, 403);
    assert_eq!(answers["/allowed"].status, 200);
    assert_eq!(answers["/also-allowed"].status, 200);

    // The blocked one never reached the origin; the others did.
    let paths: Vec<String> = origin
        .requests()
        .into_iter()
        .map(|request| request.path)
        .collect();
    assert!(!paths.contains(&"/blocked".to_owned()));
    assert_eq!(paths.len(), 2);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_blocked_stream_leaves_the_connection_usable() {
    let origin = echoing_origin().await;
    let proxy = Proxy::ruled(
        origin.trust(),
        Capture::with_defaults(),
        one_rule("block it", HOST, "/blocked", block(403)),
    )
    .await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    assert_eq!(
        connection
            .send("GET", "/blocked", &[], Vec::new())
            .await
            .status,
        403
    );
    assert_eq!(
        connection
            .send("GET", "/after", &[], Vec::new())
            .await
            .status,
        200
    );

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn map_local_answers_an_http_2_stream_from_a_file() {
    let directory = tempfile::tempdir().expect("a temporary directory");
    let fixture = directory.path().join("users.json");
    std::fs::write(&fixture, r#"{"users":["local"]}"#).expect("write the fixture");

    let origin = echoing_origin().await;
    let proxy = Proxy::ruled(
        origin.trust(),
        Capture::with_defaults(),
        one_rule(
            "answer it locally",
            HOST,
            "/users",
            RuleAction::MapLocal(MapLocal::new(&fixture)),
        ),
    )
    .await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/users")
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), r#"{"users":["local"]}"#);
    assert_eq!(response.header("content-type"), Some("application/json"));
    assert_eq!(response.version, Version::HTTP_2);
    // Nothing was sent upstream.
    assert!(origin.requests().is_empty());

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn map_remote_sends_an_http_2_stream_to_another_http_2_origin() {
    let intended = echoing_origin().await;
    let mapped = Http2Origin::responding_with(HOST, Http2Reply::ok("from the mapped origin")).await;
    let proxy = Proxy::ruled(
        trusting_all(&[intended.trust(), mapped.trust()]),
        Capture::with_defaults(),
        one_rule(
            "send it elsewhere",
            HOST,
            "/original",
            map_remote(&format!("https://{}/mapped", mapped.authority())),
        ),
    )
    .await;

    let response = client(&proxy)
        .exchange(
            proxy.addr(),
            &intended.authority(),
            HOST,
            "GET",
            "/original",
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "from the mapped origin");

    // It went where the rule said, and nowhere else.
    assert!(intended.requests().is_empty());
    let received = mapped.only_request();
    assert_eq!(received.path, "/mapped");
    assert_eq!(received.version, Version::HTTP_2);
    assert_eq!(
        received.authority.as_deref(),
        Some(mapped.authority().as_str())
    );

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn map_remote_sends_an_http_2_stream_to_an_http_1_1_origin() {
    // The mapped destination speaks only HTTP/1.1, so the same stream has to
    // come out the other side as an HTTP/1.1 request.
    let intended = echoing_origin().await;
    let mapped = TlsOrigin::responding_with(
        HOST,
        b"HTTP/1.1 200 OK\r\nContent-Length: 21\r\n\r\nfrom the old protocol",
    )
    .await;
    let proxy = Proxy::ruled(
        trusting_all(&[intended.trust(), mapped.trust()]),
        Capture::with_defaults(),
        one_rule(
            "send it elsewhere",
            HOST,
            "/original",
            map_remote(&format!("https://{}/mapped", mapped.authority())),
        ),
    )
    .await;

    let response = client(&proxy)
        .exchange(
            proxy.addr(),
            &intended.authority(),
            HOST,
            "GET",
            "/original",
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "from the old protocol");

    let received = mapped.only_request();
    assert_eq!(received.version, "HTTP/1.1");
    assert_eq!(received.target, "/mapped");
    assert_eq!(received.header("host"), Some(mapped.authority().as_str()));

    proxy.stop().await;
}

