#[tokio::test(flavor = "multi_thread")]
async fn an_http_2_client_reaches_an_http_1_1_origin() {
    let origin = TlsOrigin::start(HOST, |request| {
        format!(
            "HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n{}",
            request.target.len() + 4,
            format_args!("got {}", request.target)
        )
        .into_bytes()
    })
    .await;
    let proxy = Proxy::trusting(origin.trust()).await;

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/api")
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.version, Version::HTTP_2);
    assert_eq!(response.body_text(), "got /api");

    // The origin saw an ordinary HTTP/1.1 request, with a `Host` header built
    // from the stream's `:authority`.
    let received = origin.only_request();
    assert_eq!(received.version, "HTTP/1.1");
    assert_eq!(received.target, "/api");
    assert_eq!(received.header("host"), Some(origin.authority().as_str()));

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_http_1_1_client_reaches_an_http_2_origin() {
    let origin = echoing_origin().await;
    let proxy = Proxy::trusting(origin.trust()).await;
    let client = HttpsClient::trusting(proxy.trust());

    let response = client
        .exchange(
            proxy.addr(),
            &origin.authority(),
            HOST,
            &support::origin_form_request("GET", "/api", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "GET /api");

    // The origin saw HTTP/2, with the client's `Host` as its `:authority`.
    let received = origin.only_request();
    assert_eq!(received.version, Version::HTTP_2);
    assert_eq!(
        received.authority.as_deref(),
        Some(origin.authority().as_str())
    );
    assert_eq!(received.header("host"), None);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_http_1_1_client_still_reaches_an_http_1_1_origin() {
    // The combination that existed before HTTP/2 did, unchanged.
    let origin =
        TlsOrigin::responding_with(HOST, b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok").await;
    let proxy = Proxy::trusting(origin.trust()).await;

    let response = HttpsClient::trusting(proxy.trust())
        .exchange(
            proxy.addr(),
            &origin.authority(),
            HOST,
            &support::origin_form_request("GET", "/", &origin.authority(), &[]),
        )
        .await;

    assert_eq!(response.status, 200);
    assert_eq!(response.body_text(), "ok");
    assert_eq!(origin.only_request().version, "HTTP/1.1");

    proxy.stop().await;
}

// ---------------------------------------------------------------------------
// Failures
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread")]
async fn an_origin_that_fails_one_stream_does_not_fail_the_others() {
    // The origin refuses one path outright and answers the rest, which is a
    // per-stream failure the client must see as one.
    let origin = Http2Origin::start(HOST, |request| {
        if request.path == "/broken" {
            Http2Reply::status(StatusCode::INTERNAL_SERVER_ERROR, "no")
        } else {
            Http2Reply::ok("fine")
        }
    })
    .await;
    let proxy = proxy_for(&origin).await;
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let answers = connection
        .send_concurrently(&["/first", "/broken", "/last"])
        .await;

    assert_eq!(answers["/first"].status, 200);
    assert_eq!(answers["/broken"].status, 500);
    assert_eq!(answers["/last"].status, 200);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_unreachable_destination_fails_only_its_own_stream() {
    // A rule maps one path to a port nothing is listening on. That mapping
    // opens its own connection, per stream, so its failure is as local as a
    // failure gets — and the streams beside it must not notice.
    let origin = echoing_origin().await;
    let dead = support::http2::unused_addr().await;
    let proxy = Proxy::ruled(
        origin.trust(),
        Capture::with_defaults(),
        one_rule(
            "send it nowhere",
            HOST,
            "/unreachable",
            map_remote(&format!("http://{dead}/gone")),
        ),
    )
    .await;
    let mut events = proxy.events();
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    let answers = connection
        .send_concurrently(&["/before", "/unreachable", "/after"])
        .await;

    assert_eq!(answers["/before"].status, 200);
    assert_eq!(answers["/unreachable"].status, 502);
    assert_eq!(answers["/after"].status, 200);

    // And the connection is still good afterwards.
    assert_eq!(
        connection
            .send("GET", "/still-here", &[], Vec::new())
            .await
            .status,
        200
    );

    let failed = next_exchanges(&mut events, 4)
        .await
        .into_iter()
        .find(|exchange| exchange.request.url.ends_with("/unreachable"))
        .expect("the failed stream is published");
    assert_eq!(
        failed.error.as_ref().map(proxy_storage::TrafficError::kind),
        Some(TrafficErrorKind::UpstreamConnect)
    );

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn an_origin_whose_certificate_does_not_verify_is_never_spoken_to() {
    // The proxy is not told to trust this origin's CA, so the upstream
    // handshake fails after the client's has succeeded. That is a failure of
    // the connection rather than of a stream, and it is captured as one.
    let origin = echoing_origin().await;
    let proxy = Proxy::start().await;
    let mut events = proxy.events();

    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    connection
        .request("GET", "/x", &[], Vec::new())
        .await
        .expect_err("the proxy could not reach the origin");

    let exchange = next_exchange(&mut events).await;
    assert_eq!(
        exchange
            .error
            .as_ref()
            .map(proxy_storage::TrafficError::kind),
        Some(TrafficErrorKind::UpstreamTls)
    );
    assert_eq!(exchange.response, None);
    // Nothing was said to the origin.
    assert!(origin.requests().is_empty());

    proxy.stop().await;
}

