// Capture, storage, and events
// ---------------------------------------------------------------------------

#[tokio::test(flavor = "multi_thread")]
async fn an_http_2_stream_is_captured_as_an_http_2_exchange() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let mut events = proxy.events();
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    connection
        .send(
            "POST",
            "/orders?rush=true",
            &[("content-type", "application/json")],
            br#"{"item":"widget"}"#.to_vec(),
        )
        .await;

    let exchange = next_exchange(&mut events).await;

    assert_eq!(exchange.request.method, "POST");
    assert_eq!(
        exchange.request.url,
        format!("https://{}/orders?rush=true", origin.authority())
    );
    // The existing model already had a word for this, so nothing was added to
    // the schema to say an exchange was HTTP/2.
    assert_eq!(exchange.request.version, HttpVersion::Http2);
    assert_eq!(
        exchange.request.headers.text("content-type"),
        Some("application/json")
    );
    assert_eq!(
        exchange.request.body.as_text(),
        Some(r#"{"item":"widget"}"#)
    );

    let response = exchange.response.as_ref().expect("a response");
    assert_eq!(response.status, 200);
    assert_eq!(response.version, HttpVersion::Http2);
    assert_eq!(response.body.as_text(), Some("POST /orders?rush=true"));

    assert_eq!(exchange.connection.scheme, Scheme::Https);
    assert_eq!(
        exchange
            .connection
            .destination
            .as_ref()
            .map(|d| d.host.as_str()),
        Some(HOST)
    );

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn each_stream_is_timed_on_its_own() {
    let origin = echoing_origin().await;
    let proxy = proxy_for(&origin).await;
    let mut events = proxy.events();
    let connection = client(&proxy)
        .connect(proxy.addr(), &origin.authority(), HOST)
        .await;

    // Two streams a moment apart on one long-lived connection. If the
    // connection's lifetime were the timing, the second would be timed from
    // the handshake and would report the pause as its own.
    connection.send("GET", "/first", &[], Vec::new()).await;
    tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    connection.send("GET", "/second", &[], Vec::new()).await;

    let exchanges = next_exchanges(&mut events, 2).await;

    for exchange in &exchanges {
        let elapsed = exchange
            .timing
            .completed_micros
            .expect("a finished exchange is timed");

        assert!(
            elapsed < 100_000,
            "{} took {elapsed}µs, which is the connection's age and not the stream's",
            exchange.request.url
        );
    }
    // And they started at different times, so they are two exchanges rather
    // than one recorded twice.
    assert_ne!(exchanges[0].id, exchanges[1].id);

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_body_over_the_limit_is_forwarded_in_full_and_captured_in_part() {
    let full = "x".repeat(4096);
    let answered = full.clone();
    let origin = Http2Origin::start(HOST, move |_| Http2Reply::ok(answered.clone())).await;
    let proxy = Proxy::capturing(
        origin.trust(),
        Capture::new(CaptureConfig::new(64), EventPublisher::new()),
    )
    .await;
    let mut events = proxy.events();

    let response = client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/big")
        .await;

    // The client got all of it.
    assert_eq!(response.body.len(), 4096);
    assert_eq!(response.body_text(), full);

    // The capture kept the limit and says how much there was.
    let exchange = next_exchange(&mut events).await;
    let body = &exchange.response.as_ref().expect("a response").body;
    assert_eq!(body.data().len(), 64);
    assert_eq!(body.size(), 4096);
    assert!(body.is_truncated());

    proxy.stop().await;
}

#[tokio::test(flavor = "multi_thread")]
async fn a_blocked_stream_is_published_as_the_exchange_it_was() {
    let origin = echoing_origin().await;
    let proxy = Proxy::ruled(
        origin.trust(),
        Capture::with_defaults(),
        one_rule("block it", HOST, "/blocked", block(451)),
    )
    .await;
    let mut events = proxy.events();

    client(&proxy)
        .exchange(proxy.addr(), &origin.authority(), HOST, "GET", "/blocked")
        .await;

    let exchange = next_exchange(&mut events).await;
    assert_eq!(exchange.request.version, HttpVersion::Http2);
    assert_eq!(exchange.status(), Some(451));

    proxy.stop().await;
}
